type State int

const (
	Closed State = iota // calls flow, outcomes counted
	Open                // fail fast, no call made
	HalfOpen            // admit a few probes to test recovery
)

func (b *Breaker) Allow() bool {
	switch b.state {
	case Open:
		return time.Since(b.openedAt) >= b.cooldown // ready to probe?
	case HalfOpen:
		return b.probes < b.maxProbes // only a few trial calls
	default: // Closed
		return true
	}
}
// Output (state after 3 forced failures, threshold 3): Open

// gobreaker ReadyToTrip: trip on a failure RATIO over a rolling window,
// not on a single unlucky burst.
st := gobreaker.Settings{
	Name:     "orders-db",
	Interval: 10 * time.Second, // rolling window: counts reset each Interval
	ReadyToTrip: func(c gobreaker.Counts) bool {
		if c.Requests < 20 { // require a minimum sample size
			return false
		}
		ratio := float64(c.TotalFailures) / float64(c.Requests)
		return ratio >= 0.5 // >50% failures over >=20 requests
	},
}
cb := gobreaker.NewCircuitBreaker(st)
_ = cb
// Output: breaker trips only once failures exceed 50% of >=20 requests

// Lazy, pull-based transition: no background timer needed.
func (b *Breaker) beforeRequest() error {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.state == Open {
		if time.Since(b.openedAt) >= b.cooldown {
			b.state = HalfOpen // cooldown elapsed: admit probes
			b.probes = 0
			return nil
		}
		return ErrOpen // still cooling down: fail fast
	}
	if b.state == HalfOpen && b.probes >= b.maxProbes {
		return ErrOpen // probe budget spent; wait for outcome
	}
	return nil
}
// Output: after the cooldown, exactly maxProbes trial calls are admitted

cb := gobreaker.NewCircuitBreaker(gobreaker.Settings{
	Name:        "payments",
	MaxRequests: 1,                // probes allowed in Half-Open
	Timeout:     5 * time.Second,  // cooldown before Half-Open
	ReadyToTrip: func(c gobreaker.Counts) bool { return c.ConsecutiveFailures >= 3 },
	OnStateChange: func(name string, from, to gobreaker.State) {
		log.Printf("breaker %q: %v -> %v", name, from, to)
	},
})

body, err := cb.Execute(func() (any, error) {
	resp, err := http.Get("https://pay.example/charge")
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	return io.ReadAll(resp.Body)
})
if errors.Is(err, gobreaker.ErrOpenState) {
	// breaker is open: serve a fallback instead of calling the dependency
}
_ = body
// Output (after 3 failures): breaker "payments": closed -> open

// bulkhead -> breaker -> timeout-wrapped attempt -> fallback
func getUser(ctx context.Context, cb *gobreaker.CircuitBreaker, sem chan struct{}, id string) User {
	select {
	case sem <- struct{}{}: // bulkhead: bound in-flight calls
		defer func() { <-sem }()
	default:
		return cachedUser(id) // at capacity: fail fast to fallback
	}
	v, err := cb.Execute(func() (any, error) {
		ctx, cancel := context.WithTimeout(ctx, 200*time.Millisecond)
		defer cancel() // bound each attempt
		return fetchUser(ctx, id)
	})
	if err != nil {
		return cachedUser(id) // breaker open or call failed -> fallback
	}
	return v.(User)
}

func withRetry(ctx context.Context, cb *gobreaker.CircuitBreaker, r *rand.Rand, do func() (any, error)) (any, error) {
	const base = 50 * time.Millisecond
	var err error
	for attempt := 0; attempt < 5; attempt++ {
		var v any
		if v, err = cb.Execute(do); err == nil {
			return v, nil
		}
		if errors.Is(err, gobreaker.ErrOpenState) {
			return nil, err // known-down: stop hammering it
		}
		ceil := time.Duration(float64(base) * math.Pow(2, float64(attempt)))
		sleep := time.Duration(r.Int63n(int64(ceil) + 1)) // full jitter in [0, ceil)
		select {
		case <-time.After(sleep):
		case <-ctx.Done():
			return nil, ctx.Err()
		}
	}
	return nil, err
}
// Output: once the breaker opens, retries return ErrOpenState immediately

