package solution

import (
	"errors"
	"sync"
	"time"
)

var ErrOpen = errors.New("circuit breaker is open")

type state int

const (
	closedState state = iota
	openState
	halfOpenState
)

type Breaker struct {
	mu          sync.Mutex
	state       state
	failures    int           // consecutive failures while closed
	maxFailures int           // threshold to trip open
	cooldown    time.Duration // how long to stay open
	openedAt    time.Time     // when we last opened
	now         func() time.Time // injected clock for testability
}

func NewBreaker(maxFailures int, cooldown time.Duration, now func() time.Time) *Breaker {
	if now == nil {
		now = time.Now // default to the real clock
	}
	if maxFailures < 1 {
		maxFailures = 1
	}
	return &Breaker{
		state:       closedState,
		maxFailures: maxFailures,
		cooldown:    cooldown,
		now:         now,
	}
}

// Execute runs fn if the breaker allows it. It returns ErrOpen when the
// breaker is open (without calling fn), otherwise fn's error.
func (b *Breaker) Execute(fn func() error) error {
	// beforeRequest decides admission and may transition Open -> Half-Open.
	if err := b.beforeRequest(); err != nil {
		return err
	}
	err := fn()
	b.afterRequest(err == nil)
	return err
}

func (b *Breaker) beforeRequest() error {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.state == openState {
		// Lazily check the cooldown against the injected clock.
		if b.now().Sub(b.openedAt) >= b.cooldown {
			b.state = halfOpenState // admit a single probe
			return nil
		}
		return ErrOpen // still cooling down: fail fast
	}
	return nil
}

func (b *Breaker) afterRequest(success bool) {
	b.mu.Lock()
	defer b.mu.Unlock()
	switch b.state {
	case halfOpenState:
		if success {
			b.state = closedState // probe healed it
			b.failures = 0
		} else {
			b.trip() // probe failed: re-open and restart cooldown
		}
	case closedState:
		if success {
			b.failures = 0
		} else {
			b.failures++
			if b.failures >= b.maxFailures {
				b.trip()
			}
		}
	}
}

// trip opens the breaker and records the time using the injected clock.
func (b *Breaker) trip() {
	b.state = openState
	b.openedAt = b.now()
	b.failures = 0
}

