// callWithRetry adds a breaker, jittered exponential backoff, and ctx awareness.
func callWithRetry(ctx context.Context, cb *Breaker, r *rand.Rand, do func() error) error {
	const base = 50 * time.Millisecond
	var err error
	for attempt := 0; attempt < 5; attempt++ {
		// Breaker short-circuits instantly once open -> no retry storm.
		err = cb.Execute(do)
		if err == nil {
			return nil
		}
		if errors.Is(err, ErrOpen) {
			return err // dependency is known-down; stop hammering it
		}
		// Exponential backoff with full jitter, in [0, base*2^attempt).
		backoff := time.Duration(float64(base) * math.Pow(2, float64(attempt)))
		sleep := time.Duration(r.Int63n(int64(backoff) + 1))
		select {
		case <-time.After(sleep):
		case <-ctx.Done(): // deadline/cancel stops retries immediately
			return ctx.Err()
		}
	}
	return err
}

func WithBulkhead(limit int) func(ctx context.Context) (func(), error) {
	sem := make(chan struct{}, limit) // buffered channel = counting semaphore
	return func(ctx context.Context) (func(), error) {
		select {
		case sem <- struct{}{}: // acquired a slot
			var once sync.Once
			release := func() { once.Do(func() { <-sem }) } // idempotent release
			return release, nil
		case <-ctx.Done(): // full and the caller's deadline/cancel fired
			return nil, ctx.Err()
		}
	}
}

package breaker

import (
	"sync"
	"time"
)

type bucket struct {
	successes, failures int
}

// RollingWindow is a ring of per-second buckets over the last `size` seconds.
type RollingWindow struct {
	mu      sync.Mutex
	buckets []bucket
	size    int              // number of 1s buckets in the window
	lastSec int64            // unix second of the most recent write
	now     func() time.Time // injected clock for testability
}

func NewRollingWindow(size int, now func() time.Time) *RollingWindow {
	if now == nil {
		now = time.Now
	}
	if size < 1 {
		size = 1
	}
	return &RollingWindow{
		buckets: make([]bucket, size),
		size:    size,
		lastSec: now().Unix(),
		now:     now,
	}
}

// Record adds one outcome to the current-second bucket, expiring stale ones.
func (w *RollingWindow) Record(success bool) {
	w.mu.Lock()
	defer w.mu.Unlock()
	w.advance()
	b := &w.buckets[int(w.now().Unix())%w.size]
	if success {
		b.successes++
	} else {
		b.failures++
	}
}

// Stats returns total requests and the failure ratio over the window.
func (w *RollingWindow) Stats() (requests int, failureRatio float64) {
	w.mu.Lock()
	defer w.mu.Unlock()
	w.advance()
	var failures int
	for i := range w.buckets {
		requests += w.buckets[i].successes + w.buckets[i].failures
		failures += w.buckets[i].failures
	}
	if requests == 0 {
		return 0, 0
	}
	return requests, float64(failures) / float64(requests)
}

// advance zeroes any buckets that have rolled out of the window since lastSec.
func (w *RollingWindow) advance() {
	sec := w.now().Unix()
	if sec == w.lastSec {
		return
	}
	elapsed := sec - w.lastSec
	if elapsed >= int64(w.size) {
		for i := range w.buckets { // whole window expired
			w.buckets[i] = bucket{}
		}
	} else {
		for s := w.lastSec + 1; s <= sec; s++ { // clear only the crossed seconds
			w.buckets[int(s)%w.size] = bucket{}
		}
	}
	w.lastSec = sec
}

// ShouldTrip reports whether the window justifies opening the breaker.
func (w *RollingWindow) ShouldTrip(minRequests int, threshold float64) bool {
	req, ratio := w.Stats()
	return req >= minRequests && ratio >= threshold
}
